"""SoftwareEngineerResult encapsulating generation outcomes.
"""

from typing import Any, Dict, List
from pydantic import BaseModel, Field


class SoftwareEngineerResult(BaseModel):
    """Outcome payload generated by Software Engineering Agent execution runs."""

    success: bool = Field(..., description="True if operation completed successfully.")
    message: str = Field("", description="Detailed output message.")
    summary: str = Field("", description="Short summary of work done.")
    artifacts: List[str] = Field(default_factory=list, description="Paths of files or artifacts created.")
    metrics: Dict[str, Any] = Field(default_factory=dict, description="Performance metrics of execution run.")
    execution_time: float = Field(0.0, description="Duration in seconds.")
